package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.util.*;
final class EventTools {
    EventTools(WorldStudio ui){ui.action("Eventos","Novo evento",()->edit(ui,null));ui.action("Eventos","Editar evento",()->{String id=(String)JOptionPane.showInputDialog(ui,"Evento","Editar",JOptionPane.PLAIN_MESSAGE,null,ui.document.triggers().stream().map(WorldDocument.Trigger::id).toArray(String[]::new),null);if(id!=null)edit(ui,ui.document.triggers().stream().filter(t->t.id().equals(id)).findFirst().orElseThrow());});ui.action("Eventos","Remover evento",()->{String id=(String)JOptionPane.showInputDialog(ui,"Evento","Remover",JOptionPane.PLAIN_MESSAGE,null,ui.document.triggers().stream().map(WorldDocument.Trigger::id).toArray(String[]::new),null);if(id!=null){var next=ui.document.withTriggers(ui.document.triggers().stream().filter(t->!t.id().equals(id)).toList());StudioEvents.validate(next);ui.change(next);}});}
    void edit(WorldStudio ui,WorldDocument.Trigger old){String[] labels={"ID","Gatilho: ENTER, AREA, INTERACT, NEAR_NPC:id, QUEST_DONE:id, MANUAL","Acao: MESSAGE, ENVIRONMENT, PORTAL, INTERACTION, CHAIN","Destino: modo/portal/evento ou vazio","Mensagem","X","Y","Largura","Altura"};String[] values=old==null?new String[]{EditorOperations.id(),"AREA","MESSAGE","","Bem-vindo",""+Math.max(0,Math.min(ui.document.width()-32,ui.lastCursor.x)),""+Math.max(0,Math.min(ui.document.height()-32,ui.lastCursor.y)),"32","32"}:new String[]{old.id(),old.when(),old.action(),old.target(),old.message(),""+old.x(),""+old.y(),""+old.width(),""+old.height()};JPanel form=new JPanel(new GridLayout(0,2,4,4));JTextField[] f=new JTextField[9];for(int i=0;i<f.length;i++){form.add(new JLabel(labels[i]));f[i]=new JTextField(values[i]);form.add(f[i]);}JCheckBox once=new JCheckBox("Uma vez por sessao",old==null||old.once());form.add(once);if(JOptionPane.showConfirmDialog(ui,form,"Evento controlado",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;var t=new WorldDocument.Trigger(f[0].getText(),f[1].getText(),f[2].getText(),f[3].getText(),f[4].getText(),Integer.parseInt(f[5].getText()),Integer.parseInt(f[6].getText()),Integer.parseInt(f[7].getText()),Integer.parseInt(f[8].getText()),once.isSelected());var events=new ArrayList<>(ui.document.triggers());if(old!=null)events.remove(old);events.add(t);var next=ui.document.withTriggers(events);StudioEvents.validate(next);ui.change(next);}
}
